<?php
namespace Ishep\Http\Controllers;use Ishep\Bootstrap\Application as App;use Ishep\Http\Response;final class DashboardController{public function show(string $view,string $title):Response{$app=App::instance();$id=(int)($app->auth()->user()['id']??0);$canReview=$app->authorization()->hasRole($id,'administrator')||$app->authorization()->hasRole($id,'super_user');return$app->render('dashboards/'.$view,['title'=>$title,'canReviewApplications'=>$canReview,'applicationCounts'=>$canReview?$app->applications()->counts():[]]);}}
